-- MP-0026: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0026: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0026: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='wawasan' and type='party') then raise exception 'MP-0026: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('saifuddin-abdullah','wan-razali-wan-nor','mohd-shahar-abdullah') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0026: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('indera mahkota','kuantan','paya besar') and slug not in ('saifuddin-abdullah','wan-razali-wan-nor','mohd-shahar-abdullah')) then raise exception 'MP-0026: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0026:%' and (m.source_type <> 'editorial' or e.slug not in ('saifuddin-abdullah','wan-razali-wan-nor','mohd-shahar-abdullah') or m.import_key not like 'MP-0026:' || e.slug || ':%')) then raise exception 'MP-0026: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'saifuddin-abdullah','Saifuddin Abdullah','opposition','Member of the Dewan Rakyat; Secretary-General of Parti Wawasan Negara','Indera Mahkota','Pahang','Saifuddin Abdullah represents Indera Mahkota, Pahang, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; Secretary-General of Parti Wawasan Negara. A Parti Wawasan Negara member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4121','/portraits/saifuddin-abdullah.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P082.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4121"}, {"label": "Wawasan · announced leadership, 21 June 2026", "url": "https://www.thestar.com.my/news/nation/2026/06/21/parti-wawasan-negara-unveils-central-leadership-line-up"}]'::jsonb from public.entities parent where parent.slug='wawasan' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wan-razali-wan-nor','Wan Razali Wan Nor','opposition','Member of the Dewan Rakyat','Kuantan','Pahang','Wan Razali Wan Nor represents Kuantan, Pahang, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4122','/portraits/wan-razali-wan-nor.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P083.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4122"}, {"label": "PAS · parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-shahar-abdullah','Mohd Shahar Abdullah','government','Deputy Minister of Economy','Paya Besar','Pahang','Mohd Shahar Abdullah represents Paya Besar, Pahang, in the Dewan Rakyat. Current role: Deputy Minister of Economy. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4123','/portraits/mohd-shahar-abdullah.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P084.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4123"}, {"label": "UMNO · Paya Besar division chief, 29 July 2026", "url": "https://umno-online.my/2026/07/29/bukan-hanya-di-pentas-politik-pemimpin-bn-juga-hebat-di-padang-bola/"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('saifuddin-abdullah','wan-razali-wan-nor','mohd-shahar-abdullah') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0026: concurrent ownership or identity change'; end if; end $$;

